INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('fd5600a3-0646-49ae-b83c-b48815bd4835', 'a1b2c3d4-2222-4000-8000-000000000002', 6, 'Perseverança na Oração', 'Quando Deus parece silencioso', '{"intro": "Todo orante passa pelo deserto \u2014 a \"noite escura\" de S\u00e3o Jo\u00e3o da Cruz. S\u00e3o momentos em que Deus parece ausente, a ora\u00e7\u00e3o parece vazia e o cora\u00e7\u00e3o est\u00e1 seco. Mas \u00e9 justamente a\u00ed que a f\u00e9 se purifica. Madre Teresa de Calcut\u00e1 viveu 50 anos de aridez espiritual \u2014 e nunca deixou de rezar. A perseveran\u00e7a na ora\u00e7\u00e3o n\u00e3o \u00e9 hero\u00edsmo; \u00e9 confian\u00e7a de que Deus est\u00e1 trabalhando no escuro.", "prayer": "Deus fiel, mesmo quando n\u00e3o Te sinto, sei que est\u00e1s aqui. D\u00e1-me a gra\u00e7a de perseverar na ora\u00e7\u00e3o, confiando que Tu ages no sil\u00eancio. Am\u00e9m.", "practice": "Fa\u00e7a um compromisso escrito: \"Eu me comprometo a rezar todos os dias, por pelo menos 10 minutos, durante os pr\u00f3ximos 30 dias \u2014 mesmo quando n\u00e3o sentir vontade.\" Assine e date.", "scripture": "\"Vigia e ora, para que n\u00e3o entreis em tenta\u00e7\u00e3o. O esp\u00edrito est\u00e1 pronto, mas a carne \u00e9 fraca.\" \u2014 Mt 26,41", "reflection": "Voc\u00ea j\u00e1 passou por per\u00edodos de aridez na ora\u00e7\u00e3o? Como reagiu? O que aprendeu com isso?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;